import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) {
        InputReader in = new InputReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        final int MOD = 998244353;
        int n = in.nextInt();
        int k = in.nextInt();
        int[] base = new int[10];
        for (int i = 0; i < k; i++) {
            base[in.nextInt()] = 1;
        }

        int[] ans = new int[]{1};
        int exp = n / 2;
        while (exp > 0) {
            if ((exp & 1) == 1) {
                ans = polyMultiply(ans, base, MOD);
            }
            base = polyMultiply(base, base, MOD);
            exp >>= 1;
        }

        long sum = 0;
        for (int val : ans) {
            sum = (sum + (long)val * val) % MOD;
        }
        out.println(sum);
        out.close();
    }

    static int[] polyMultiply(int[] a, int[] b, int mod) {
        int lenA = a.length, lenB = b.length;
        int resultSize = lenA + lenB - 1;
        int fftLen = 1;
        while (fftLen < resultSize) fftLen <<= 1;

        double[] reA = new double[fftLen];
        double[] imA = new double[fftLen];
        double[] reB = new double[fftLen];
        double[] imB = new double[fftLen];

        for (int i = 0; i < lenA; i++) {
            long val = ((long)a[i] % mod + mod) % mod;
            reA[i] = val & 0x7fff;
            imA[i] = val >>> 15;
        }
        for (int i = 0; i < lenB; i++) {
            long val = ((long)b[i] % mod + mod) % mod;
            reB[i] = val & 0x7fff;
            imB[i] = val >>> 15;
        }

        performFFT(reA, imA, false);
        performFFT(reB, imB, false);

        double[] resRe = new double[fftLen];
        double[] resIm = new double[fftLen];
        double[] extraRe = new double[fftLen];
        double[] extraIm = new double[fftLen];

        double scaleFactor = 0.25 / fftLen;
        for (int i = 0; i < fftLen; i++) {
            int j = (fftLen - i) & (fftLen - 1);

            double a1r = (reA[i] + reA[j]) * 0.5;
            double a1i = (imA[i] - imA[j]) * 0.5;
            double a2r = (imA[i] + imA[j]) * 0.5;
            double a2i = (reA[j] - reA[i]) * 0.5;

            double b1r = (reB[i] + reB[j]) * 0.5;
            double b1i = (imB[i] - imB[j]) * 0.5;
            double b2r = (imB[i] + imB[j]) * 0.5;
            double b2i = (reB[j] - reB[i]) * 0.5;

            resRe[i] = a1r * b1r - a1i * b1i - a2r * b2i - a2i * b2r;
            resIm[i] = a1r * b1i + a1i * b1r + a2r * b2r - a2i * b2i;
            extraRe[i] = a1r * b2r - a1i * b2i + a2r * b1r - a2i * b1i;
            extraIm[i] = a1r * b2i + a1i * b2r + a2r * b1i + a2i * b1r;
        }

        performFFT(resRe, resIm, true);
        performFFT(extraRe, extraIm, true);

        int[] result = new int[resultSize];
        for (int i = 0; i < resultSize; i++) {
            long part1 = Math.round(resRe[i]);
            long part2 = Math.round(extraRe[i]);
            long part3 = Math.round(resIm[i]);
            result[i] = (int)((part1 + ((part2 % mod) << 15) + ((part3 % mod) << 30)) % mod);
        }
        return result;
    }

    static void performFFT(double[] re, double[] im, boolean inverse) {
        int n = re.length;
        int leadingZeros = Integer.numberOfLeadingZeros(n);
        int bitReverseShift = 32 - leadingZeros;
        for (int i = 1; i < n; i++) {
            int j = Integer.reverse(i) >>> bitReverseShift;
            if (i < j) {
                double temp = re[i]; re[i] = re[j]; re[j] = temp;
                temp = im[i]; im[i] = im[j]; im[j] = temp;
            }
        }

        for (int segment = 2; segment <= n; segment <<= 1) {
            int half = segment >> 1;
            double[] cosines = new double[half];
            double[] sines = new double[half];
            double angleStep = 2 * Math.PI / segment * (inverse ? -1 : 1);
            for (int i = 0; i < half; i++) {
                cosines[i] = Math.cos(i * angleStep);
                sines[i] = Math.sin(i * angleStep);
            }

            for (int start = 0; start < n; start += segment) {
                for (int offset = 0; offset < half; offset++) {
                    double cr = cosines[offset];
                    double ci = sines[offset];
                    double ur = re[start + offset];
                    double ui = im[start + offset];
                    double vr = re[start + offset + half] * cr - im[start + offset + half] * ci;
                    double vi = re[start + offset + half] * ci + im[start + offset + half] * cr;

                    re[start + offset] = ur + vr;
                    im[start + offset] = ui + vi;
                    re[start + offset + half] = ur - vr;
                    im[start + offset + half] = ui - vi;
                }
            }
        }

        if (inverse) {
            for (int i = 0; i < n; i++) {
                re[i] /= n;
                im[i] /= n;
            }
        }
    }

    static class InputReader {
        private final InputStream inputStream;
        private final byte[] buffer = new byte[1024];
        private int bufferIndex, bufferSize;

        public InputReader(InputStream inputStream) {
            this.inputStream = inputStream;
        }

        private int read() {
            if (bufferSize == -1) throw new RuntimeException();
            if (bufferIndex >= bufferSize) {
                bufferIndex = 0;
                try { bufferSize = inputStream.read(buffer); } catch (IOException e) { throw new RuntimeException(); }
                if (bufferSize <= 0) return -1;
            }
            return buffer[bufferIndex++] & 0xff;
        }

        public int nextInt() {
            int c;
            while ((c = read()) <= ' ') if (c == -1) throw new RuntimeException();
            int sign = 1;
            if (c == '-') { sign = -1; c = read(); }
            int num = 0;
            do {
                if (c < '0' || c > '9') throw new RuntimeException();
                num = num * 10 + c - '0';
                c = read();
            } while (c > ' ');
            return num * sign;
        }
    }
}
